const e={title:"TripReel - Bezplatná Aplikace pro Animaci Cestování: Převeďte Fotografie na Krásná Videa",description:"Vytvořte úžasná cestovní videa s animovanými mapami a trasami letů. Bezplatná aplikace pro animaci cestování s 3D mapováním tras glóbu. Automaticky převeďte své fotografie na krásná cestovní videa. Soukromí na prvním místě, funguje offline.",keywords:"aplikace pro animaci cestování, aplikace pro animaci mapy cestování, aplikace pro animaci trasy cestování, aplikace pro animaci letu, tvůrce cestovních videí, automatické cestovní video, animovaná mapa cestování, animace trasy letu, animace cestování, animace glóbu, video rekapitulace cestování, foto na video, zvýraznění cestování, bezplatná aplikace pro cestování, tvůrce videa offline, soukromá aplikace pro cestování, video z rolky kamery"},o={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Jak to funguje",video:"Video",features:"Funkce",theApp:"Aplikace"},t={badge:"Proměňte fotky v cestovatelské příběhy",title1:"Vaše fotogalerie,",title2:"naplno využitá",description:"TripReel automaticky vytváří krásná cestovatelská videa z polohy vašich fotek. Sledujte, jak vaše cesty ožívají s úžasnými animovanými trasami a leteckými cestami na 3D glóbu, zatímco vaše data zůstávají v bezpečí a soukromí.",secure:"100% zabezpečeno",worksOffline:"Funguje offline",globeAlt:"Animace glóbu TripReel"},a={title:"Jak to funguje",subtitle:"Tři jednoduché kroky k vytvoření dokonalého cestovatelského videa",step1:{title:"Povolte přístup k fotkám",description:"Udělte TripReel přístup k vaší galerii fotek. Aplikace čte pouze metadata o poloze, nic víc."},step2:{title:"Automatické rozpoznání cest",description:"TripReel analyzuje metadata o poloze a inteligentně najde vaše cesty na základě dat a míst."},step3:{title:"Vygenerujte video",description:"Sledujte, jak se vaše cesta odvíjí na krásné animaci glóbu, připravená ke sdílení na sociálních sítích."}},i={title:"Podívejte se na kouzlo v akci",subtitle:"Zjistěte, jak TripReel promění vaši galerii fotek v úžasná cestovatelská videa",caption:"Takhle může vypadat vaše finální cestovatelské video"},n={title:"Vše, co potřebujete",subtitle:"Výkonné funkce navržené pro moderní cestovatele",twoTap:{title:"Cestovatelská videa na dvě klepnutí",description:"Vytvořte úžasná cestovatelská videa z vaší galerie fotek jen dvěma klepnutími. Žádné úpravy nejsou potřeba."},smartTrip:{title:"Chytré rozpoznání cest",description:"Automaticky najde a seskupí vaše cesty analýzou dat a metadat o poloze z vašich fotek."},globe:{title:"Krásná animace glóbu",description:"Sledujte, jak vaše cesta ožívá na úžasném 3D glóbu zobrazujícím vaše animované cestovní trasy a letecké cesty po celém světě."},privacy:{title:"Soukromí na prvním místě",description:"Vše se zpracovává na vašem zařízení. Vaše fotky nikdy neopustí váš telefon. Funguje v letovém režimu."},customStyles:{title:"Vlastní styly",description:"Vyberte si z několika stylů glóbu a přizpůsobení, aby odpovídaly vaší estetice a každé video bylo jedinečné."},manualControl:{title:"Manuální ovládání",description:"Můžete ručně přidat zcela nové cesty, pokud nebyly na vašem zařízení povoleny polohové služby."}},s={title:"Kreativní nápady na videa",subtitle:"Nechte se inspirovat tím, co můžete vytvořit s TripReel. Od rychlých víkendových výletů po celoroční dobrodružství, vytvářejte úžasná cestovatelská videa pro každou cestu.",description:"Ať už vytváříte animaci cestovní mapy, zaznamenáváte leteckou trasu nebo tvoříte celoroční rekapitulaci cest, TripReel vám jednoduše promění vzpomínky ve videa ke sdílení.",ideas:{yearRecap:{title:"Cestování v roce 2025",description:"Vytvořte automaticky video rekapitulaci vašeho cestování za rok 2025"},europeRoadTrip:{title:"Roadtrip po Evropě",description:"Ukažte své evropské dobrodružství s animovanými mapami tras"},southeastAsia:{title:"Cesta jihovýchodní Asií",description:"Vizualizujte svou cestu s batohem napříč více zeměmi"},japanRail:{title:"Vlakem po Japonsku",description:"Vytvořte mapová videa vašich vlakových cest po Japonsku"},crossCountry:{title:"Napříč USA",description:"Proměňte svůj americký roadtrip v epické video trasy"},islandHopping:{title:"Skákání po ostrovech",description:"Ukažte své cestování z ostrova na ostrov s úžasnými 3D animacemi"},worldTour:{title:"Sestřih světového turné",description:"Více cest v jednom úžasném globálním video příběhu"},travelPlans:{title:"Cestovní plány na rok 2026",description:"Vizualizujte a naplánujte svá vzrušující dobrodružství na rok 2026"},lifetimeTravel:{title:"Příběh cestování života",description:"Vytvořte video zachycující všechny vaše celoživotní cesty"},regionalExplorer:{title:"Průzkumník regionů",description:"Zmapujte svá dobrodružství po krajích, provinciích a regionech"},festivalCircuit:{title:"Festivalový okruh",description:"Zmapujte svou cestu po hudebních festivalech a akcích"},bikeRoutes:{title:"Moje výlety do měst",description:"Ukažte všechny své městské únikové cesty"}}},l={title:"Aplikace",subtitle:"Již k dispozici v App Store",alt1:"Automatická cestovatelská videa - Vytvořte úžasná videa během pár sekund",alt2:"Detekce polohy fotek - Využívá metadata vašich fotek",alt3:"Detekce cest - Automaticky seskupuje vaše cesty",alt4:"Krásná videa glóbu - Animace glóbu vaší cesty",alt5:"Vlastní styly - Personalizujte svá cestovatelská videa"},v={comingSoon:"Již brzy",androidTitle:"Android aplikace již brzy!",androidMessage:'Verze pro Android zatím není k dispozici, ale bude brzy. Napište mi na <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> a dám vám vědět, až bude připravená!',gotIt:"Jasně!"},p={title:"Často kladené dotazy",subtitle:"Vše, co potřebujete vědět o TripReel",q1:{question:"Mohu aplikaci skutečně používat plně v letovém režimu?",answer:"Ano! Pro prémiové uživatele lze aplikaci používat kompletně offline v letovém režimu bez jakýchkoliv omezení. Pro neprémiové uživatele jsou některé funkce podporované reklamami, které mohou vyžadovat dočasné zapnutí internetu, ale prémiové uživatele žádné reklamy nečekají a aplikaci lze plně používat v letovém režimu."},q2:{question:"Upgradoval jsem na Premium, jak mohu odstranit vodoznak?",answer:"Mnoho lidí se ptá, jaká aplikace byla použita k vytvoření těchto videí, proto po upgradu na premium máte možnost přidat menší verzi vodoznaku (pouze s názvem aplikace) nebo ho úplně odstranit, pokud chcete."},q3:{question:"Jsou moje data z fotek bezpečná a soukromá?",answer:"Absolutně! TripReel čte pouze metadata o poloze z vašich fotek - nikdy nepřistupujeme k obsahu samotných fotek, neukládáme ho ani nepřenášíme. Veškeré zpracování probíhá lokálně na vašem zařízení a žádná data nikdy neopustí váš telefon. Můžete si to ověřit používáním aplikace v letovém režimu - funguje dokonale offline!"},q4:{question:"Co když moje fotky nemají data o poloze?",answer:"Žádný problém! Pokud nebyly povoleny polohové služby, když jste fotky pořizovali, můžete ručně vytvořit cesty a přidat polohy sami. Aplikace vám dává plnou kontrolu k přizpůsobení vaší cestovní časové osy."},q5:{question:"Jak aplikace automaticky rozpoznává moje cesty?",answer:"TripReel analyzuje metadata o poloze a časová razítka z vašich fotek, aby inteligentně identifikoval, kdy a kam jste cestovali. Seskupuje blízké polohy a data dohromady, aby automaticky rozpoznal vaše cesty bez jakékoli manuální práce."},q6:{question:"Mohu přizpůsobit vzhled svých videí?",answer:"Ano! Můžete si vybrat z několika stylů glóbu a přizpůsobit různé aspekty vašich animovaných cestovatelských videí, aby odpovídaly vaší osobní estetice. Prémiové uživatelé získají přístup k dalším stylům animace tras, motivům map a možnostem leteckých cest."},q7:{question:"Potřebuji si vytvořit účet?",answer:"Žádný účet není potřeba! TripReel funguje okamžitě po stažení. Není potřeba žádná registrace, žádné přihlášení a nejsou potřeba žádné osobní údaje. Prostě si stáhněte aplikaci a začněte vytvářet svá cestovatelská videa hned."},q8:{question:"Proč v mé cestě chybí nějaká poloha?",answer:"Aplikace může pracovat pouze s dostupnými daty, takže především potřebujete mít v dané poloze alespoň pár fotek. Zadruhé se musíte ujistit, že jste měli povolená data o poloze, když jste tam byli. Zatřetí někdy slabý GPS signál může způsobit chybná data o poloze. Pokud jste to všechno vyloučili a vaše poloha se stále nezobrazuje, můžete ji ručně přidat z Přehled cest > tlačítko Upravit. Prosím také použijte Kontakt k nahlášení problému."},q9:{question:"Kam mohu sdílet své úžasné video?",answer:"Samozřejmě ho můžete sdílet také na všech sociálních platformách. Pro lepší přizpůsobení platformě aplikace umožňuje různé poměry stran pro vaše videa."},q10:{question:"Kde mohu nahlásit chybu?",answer:"Jednoduše mě kontaktujte přímo na marian@qod.ee a stručně vysvětlete, o jaký problém se jedná."}},r={title:"Emailová podpora",description:"Pokud máte jakoukoli zpětnou vazbu nebo narazíte na jakékoli problémy, neváhejte mě kontaktovat přímo na tento email a osobně přečtu a vyřídím váš požadavek co nejrychleji. Děkuji, že používáte aplikaci!",close:"Zavřít"},c={default:{title:"🍪 Cookies",message:"Na webu TripReel používáme cookies pro zlepšení vašeho zážitku. Nejsou shromažďována žádná osobní data.",accept:"Přijmout",decline:"Odmítnout",details:"Podrobnosti"},theme:{title:"🍪 Cookies",message:"🌙 Pro uložení vaší preference motivu musíte přijmout základní cookies na webu TripReel. Bez nich nelze vaši volbu motivu uložit.",accept:"Přijmout",decline:"Odmítnout",details:"Podrobnosti"}},d={privacy:"Zásady ochrany soukromí aplikace",cookies:"Zásady cookies webu",contact:"Kontakt",cookiePreferences:"Předvolby cookies",madeWith:"Vytvořeno s",forTravelers:"pro cestovatele po celém světě",copyright:"© {{year}} TripReel."},u={title:"Připraveni sdílet svou cestu?",description:"Stáhněte si TripReel ještě dnes a proměňte svou fotogalerii v krásná cestovatelská videa s animovanými mapami a trasami. Vaše dobrodružství si zaslouží být oslavena.",features:"Ke stažení zdarma • Rychlé a pohodlné • Zaručené soukromí"},k={meta:e,header:o,hero:t,howItWorks:a,videoSection:i,features:n,videoIdeas:s,screenshots:l,appStore:v,faq:p,contact:r,cookieBanner:c,footer:d,cta:u};export{v as appStore,r as contact,c as cookieBanner,u as cta,k as default,p as faq,n as features,d as footer,o as header,t as hero,a as howItWorks,e as meta,l as screenshots,s as videoIdeas,i as videoSection};
